package archi

import (
	"fmt"
	"sort"
	"strings"
)

// Compact view notation (inside ArchimateDiagramModel only):
//   "o:<elementId> x y w h"      DiagramObject, nothing else but bounds
//   "c:<relationshipId>"         Connection, source/target derived from the relationship
//   {"o:<elementId>": {...}}     same, with extra attributes / kids
// Dropped when derivable: node ids nobody references, connection source/target, targetConnections.
// Regenerated by ExpandViews.

type vnode struct {
	k    string
	v, p Obj
}

func isConn(k string) bool { return strings.HasSuffix(k, "Connection") }

func collectNodes(kids []any, parent Obj, out *[]vnode) {
	for _, kid := range kids {
		ko, ok := kid.(Obj)
		if !ok {
			continue
		}
		k, v, one := ko.Single()
		if !one {
			continue
		}
		vo, ok := v.(Obj)
		if ok && (IsTypeKey(k) || k == "sourceConnection") {
			*out = append(*out, vnode{k, vo, parent})
			collectNodes(vo.List("kids"), vo, out)
		}
	}
}

func nodesOf(kids []any) []vnode {
	var out []vnode
	collectNodes(kids, nil, &out)
	return out
}

// relIndex maps relationship id -> (source, target) for every raw relationship object.
func relIndex(obj any) map[string][2]string {
	rels := map[string][2]string{}
	var walk func(x any)
	walk = func(x any) {
		switch v := x.(type) {
		case Obj:
			for _, k := range v.keys {
				val := v.m[k]
				if o, ok := val.(Obj); ok && strings.HasSuffix(k, relSuffix) && o.Has("source") && o.Has("target") && o.Has("id") {
					rels[o.Str("id")] = [2]string{o.Str("source"), o.Str("target")}
				}
				walk(val)
			}
		case []any:
			for _, i := range v {
				walk(i)
			}
		}
	}
	walk(obj)
	return rels
}

// findViews returns every ArchimateDiagramModel value (not descending into the views themselves).
func findViews(x any) []Obj {
	var out []Obj
	switch v := x.(type) {
	case Obj:
		for _, k := range v.keys {
			if o, ok := v.m[k].(Obj); ok && k == "ArchimateDiagramModel" {
				out = append(out, o)
			} else {
				out = append(out, findViews(v.m[k])...)
			}
		}
	case []any:
		for _, i := range v {
			out = append(out, findViews(i)...)
		}
	}
	return out
}

// FindViews exposes findViews to other packages.
func FindViews(x any) []Obj { return findViews(x) }

func sortedFields(s string) []string {
	f := strings.Fields(s)
	sort.Strings(f)
	return f
}

func compactView(view Obj, rels map[string][2]string) error {
	kids := view.List("kids")
	nodes := nodesOf(kids)
	for _, n := range nodes {
		if !n.v.Has("id") {
			return nil
		}
	}
	elmap := map[string][]string{}
	for _, n := range nodes {
		if n.k == "DiagramObject" && n.v.Has("archimateElement") {
			e := n.v.Str("archimateElement")
			elmap[e] = append(elmap[e], n.v.Str("id"))
		}
	}
	unique := map[string]string{}
	for e, ids := range elmap {
		if len(ids) == 1 {
			unique[e] = ids[0]
		}
	}
	incoming := map[string][]string{}
	for _, n := range nodes {
		if isConn(n.k) && n.v.Has("target") {
			t := n.v.Str("target")
			incoming[t] = append(incoming[t], n.v.Str("id"))
		}
	}
	derived := map[string]bool{}
	for _, n := range nodes {
		if n.k == "Connection" && n.v.Has("archimateRelationship") && n.p != nil {
			r, ok := rels[n.v.Str("archimateRelationship")]
			if ok && n.p.Str("id") == n.v.Str("source") && unique[r[0]] == n.v.Str("source") &&
				unique[r[1]] == n.v.Str("target") && n.v.Str("source") != "" && n.v.Str("target") != "" {
				derived[n.v.Str("id")] = true
			}
		}
	}
	dropTC := map[string]bool{}
	referenced := map[string]bool{}
	for _, n := range nodes {
		id := n.v.Str("id")
		if n.v.Has("targetConnections") {
			tc := n.v.Str("targetConnections")
			inc := append([]string(nil), incoming[id]...)
			sort.Strings(inc)
			if strings.Join(sortedFields(tc), " ") == strings.Join(inc, " ") {
				dropTC[id] = true
			} else {
				for _, x := range strings.Fields(tc) {
					referenced[x] = true
				}
			}
		} else if _, ok := incoming[id]; ok {
			return fmt.Errorf("incoming connections without targetConnections: %s", id)
		}
		if isConn(n.k) && !derived[id] {
			for _, a := range []string{"source", "target"} {
				if s := n.v.Str(a); s != "" {
					referenced[s] = true
				}
			}
		}
	}
	for _, n := range nodes {
		id := n.v.Str("id")
		if derived[id] {
			n.v.Del("source")
			n.v.Del("target")
		}
		if dropTC[id] {
			n.v.Del("targetConnections")
		}
		if !referenced[id] {
			n.v.Del("id")
		}
	}
	convertKids(kids)
	return nil
}

func convertKids(kids []any) {
	for i, kid := range kids {
		ko, ok := kid.(Obj)
		if !ok {
			continue
		}
		k, v, one := ko.Single()
		vo, isObj := v.(Obj)
		if !one || !isObj {
			continue
		}
		if sub := vo.List("kids"); vo.Has("kids") {
			convertKids(sub)
		}
		var nk, drop string
		switch {
		case k == "DiagramObject" && vo.Has("archimateElement"):
			nk, drop = "o:"+vo.Str("archimateElement"), "archimateElement"
		case k == "Connection" && vo.Has("archimateRelationship"):
			nk, drop = "c:"+vo.Str("archimateRelationship"), "archimateRelationship"
		default:
			continue
		}
		rest := NewObj()
		for _, a := range vo.keys {
			if a != drop {
				rest.Set(a, vo.m[a])
			}
		}
		switch {
		case rest.Len() == 0:
			kids[i] = nk
		case rest.KeysAre("b"):
			kids[i] = nk + " " + rest.Str("b")
		default:
			kids[i] = O(nk, rest)
		}
	}
}

// CompactViews rewrites every ArchimateDiagramModel's kids into the o:/c: notation (in place).
// Call before CompactRelations: it needs raw relationship objects.
func CompactViews(obj Obj) (Obj, error) {
	rels := relIndex(obj)
	for _, view := range findViews(obj) {
		if err := compactView(view, rels); err != nil {
			return nil, err
		}
	}
	return obj, nil
}

func normKids(kids []any) {
	for i, kid := range kids {
		if s, ok := kid.(string); ok {
			key, b, _ := strings.Cut(s, " ")
			v := NewObj()
			if b != "" {
				v.Set("b", b)
			}
			kid = O(key, v)
		}
		ko, ok := kid.(Obj)
		if !ok {
			continue
		}
		k, v, one := ko.Single()
		if !one {
			continue
		}
		vo, isObj := v.(Obj)
		if isObj && len(k) >= 2 && (k[:2] == "o:" || k[:2] == "c:") {
			nv := NewObj()
			if vo.Has("id") {
				nv.Set("id", vo.Get("id"))
			}
			var nk string
			if k[0] == 'o' {
				nv.Set("archimateElement", k[2:])
				nk = "DiagramObject"
			} else {
				nk = "Connection"
				for _, a := range []string{"source", "target"} {
					if vo.Has(a) {
						nv.Set(a, vo.Get(a))
					}
				}
				nv.Set("archimateRelationship", k[2:])
			}
			for _, a := range vo.keys {
				if a != "id" && a != "source" && a != "target" {
					nv.Set(a, vo.m[a])
				}
			}
			kid = O(nk, nv)
			vo = nv
		}
		if vo != nil && vo.Has("kids") {
			normKids(vo.List("kids"))
		}
		kids[i] = kid
	}
}

func reorderFirst(v Obj, first ...[2]any) {
	items := make([][2]any, 0, v.Len())
	for _, k := range v.keys {
		items = append(items, [2]any{k, v.m[k]})
	}
	v.keys, v.m = nil, map[string]any{}
	for _, f := range first {
		v.Set(f[0].(string), f[1])
	}
	for _, it := range items {
		if !v.Has(it[0].(string)) {
			v.Set(it[0].(string), it[1])
		}
	}
}

func expandView(view Obj, rels map[string][2]string, gen func() string) error {
	kids := view.List("kids")
	normKids(kids)
	nodes := nodesOf(kids)
	for _, n := range nodes {
		if !n.v.Has("id") {
			n.v.Prepend("id", gen())
		}
	}
	elmap := map[string][]string{}
	for _, n := range nodes {
		if n.k == "DiagramObject" && n.v.Has("archimateElement") {
			e := n.v.Str("archimateElement")
			elmap[e] = append(elmap[e], n.v.Str("id"))
		}
	}
	unique := map[string]string{}
	for e, ids := range elmap {
		if len(ids) == 1 {
			unique[e] = ids[0]
		}
	}
	for _, n := range nodes {
		if n.k == "Connection" && !n.v.Has("source") {
			rid := n.v.Str("archimateRelationship")
			r, ok := rels[rid]
			if !ok {
				return fmt.Errorf("view connection refers to unknown relationship %s", PyRepr(rid))
			}
			s, ok1 := unique[r[0]]
			t, ok2 := unique[r[1]]
			if !ok1 || !ok2 {
				return fmt.Errorf("cannot derive connection ends of relationship %s: element not drawn exactly once", PyRepr(rid))
			}
			id := n.v.Get("id")
			n.v.Del("id")
			reorderFirst(n.v, [2]any{"id", id}, [2]any{"source", s}, [2]any{"target", t})
		}
	}
	nestConnections(view, kids)
	nodes = nodesOf(view.List("kids"))
	incoming := map[string][]string{}
	for _, n := range nodes {
		if isConn(n.k) && n.v.Has("target") {
			t := n.v.Str("target")
			incoming[t] = append(incoming[t], n.v.Str("id"))
		}
	}
	for _, n := range nodes {
		id := n.v.Str("id")
		if !n.v.Has("targetConnections") && len(incoming[id]) > 0 {
			reorderFirst(n.v, [2]any{"id", id}, [2]any{"targetConnections", strings.Join(incoming[id], " ")})
		}
	}
	return nil
}

// nestConnections moves each connection into its source node (Archi requires that).
func nestConnections(view Obj, rootKids []any) {
	byID := map[string]Obj{}
	for _, n := range nodesOf(rootKids) {
		byID[n.v.Str("id")] = n.v
	}
	type move struct {
		owner Obj
		kid   Obj
		src   string
	}
	var moves []move
	var scan func(owner Obj, kids []any, ownerID string)
	scan = func(owner Obj, kids []any, ownerID string) {
		for _, kid := range kids {
			ko, ok := kid.(Obj)
			if !ok {
				continue
			}
			k, v, one := ko.Single()
			vo, isObj := v.(Obj)
			if !one || !isObj {
				continue
			}
			if isConn(k) && vo.Str("source") != "" && vo.Str("source") != ownerID && byID[vo.Str("source")] != nil {
				moves = append(moves, move{owner, ko, vo.Str("source")})
			}
			scan(vo, vo.List("kids"), vo.Str("id"))
		}
	}
	scan(view, rootKids, "")
	for _, m := range moves {
		old := m.owner.List("kids")
		nl := make([]any, 0, len(old))
		for _, k := range old {
			if ko, ok := k.(Obj); !ok || ko != m.kid {
				nl = append(nl, k)
			}
		}
		m.owner.Set("kids", nl)
		dst := byID[m.src]
		dst.Set("kids", append(dst.List("kids"), m.kid))
	}
}

// ExpandViews restores full view nodes from the o:/c: notation (in place).
// Call after ExpandRelations: it needs raw relationship objects.
func ExpandViews(obj Obj) (Obj, error) {
	rels := relIndex(obj)
	taken := map[string]bool{}
	CollectIDs(obj, taken)
	gen := NewIDGen("d", taken)
	for _, view := range findViews(obj) {
		if err := expandView(view, rels, gen); err != nil {
			return nil, err
		}
	}
	return obj, nil
}
